export function ActionSheet({
  title = "{{title}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
  width = {{width}},
  backdrop = {{backdrop}},
}) {
  const wrap = {
    grouped: { boxShadow: "0 -8px 28px rgba(36,20,48,.18)" },
    flat: { boxShadow: "none", border: "1px solid #24143020" },
    cards: { background: "none", boxShadow: "none", display: "flex", flexDirection: "column", gap: 8 },
  }[variant] ?? {};
  const rowBorder = variant === "cards" ? "none" : (variant === "flat" ? "1px solid #24143020" : "1px solid #24143014");
  const rowStyle = {
    display: "block", width: "100%", padding: 14, border: "none",
    borderBottom: rowBorder, background: variant === "cards" ? "#FAF7F2" : "none",
    borderRadius: variant === "cards" ? 12 : 0,
    boxShadow: variant === "cards" ? "0 2px 8px rgba(36,20,48,.10)" : "none",
    font: "500 16px system-ui, sans-serif", color: "#241430", cursor: "pointer", textAlign: "center",
  };
  return (
    <div style={{ position: "relative", minHeight: 440, display: "flex", alignItems: "flex-end",
      justifyContent: "center", padding: 20, boxSizing: "border-box", borderRadius: 12,
      background: "linear-gradient(135deg, #BFD9F2, #D9C8F0)" }}>
      {backdrop && <div style={{ position: "absolute", inset: 0, background: "rgba(36,20,48,.45)" }} />}
      <div role="dialog" aria-modal="true" aria-labelledby="as-title" style={{ position: "relative",
        zIndex: 1, width, margin: "0 auto", boxSizing: "border-box", fontFamily: "system-ui, sans-serif", color: "#241430" }}>
        <div aria-hidden="true" style={{ width: 36, height: 4, borderRadius: 2, background: "#24143033", margin: "0 auto 10px" }} />
        <h3 id="as-title" style={{ margin: "0 0 10px", textAlign: "center", fontSize: 13, fontWeight: 600,
          color: "#24143099", textTransform: "uppercase", letterSpacing: ".04em" }}>{title}</h3>
        <div style={{ borderRadius: 14, overflow: "hidden", ...wrap }}>
          <button type="button" style={rowStyle}>Save image</button>
          <button type="button" style={rowStyle}>Copy link</button>
          <button type="button" style={{ ...rowStyle, color: accent }}>Delete</button>
        </div>
        <button type="button" style={{ display: "block", width: "100%", marginTop: 8, padding: 14,
          border: "none", borderRadius: 14, background: "#FAF7F2", fontWeight: 600, fontSize: 16,
          cursor: "pointer", boxShadow: "0 -4px 16px rgba(36,20,48,.12)" }}>Cancel</button>
      </div>
    </div>
  );
}
